:root{font-family:"Segoe UI","Microsoft YaHei",sans-serif;color:#443c31;background:#f6f3ed;font-size:15px;color-scheme:light}
*{box-sizing:border-box}body{margin:0}button,input,textarea{font:inherit}button{cursor:pointer;border:1px solid #d7cebc;background:transparent;color:#766344;border-radius:5px;padding:9px 15px}
button:disabled{cursor:default;opacity:.5}button:focus-visible,input:focus-visible,textarea:focus-visible,summary:focus-visible{outline:3px solid #5e9bdf;outline-offset:3px}
#app{max-width:1060px;margin:20px auto 28px;padding:0 36px}.work-heading h1{font-family:"Songti SC","SimSun",serif;font-size:24px;margin:0 0 18px}.navigation h2{font-size:12px;color:#928572;font-weight:400;margin:0 0 6px}
#chapters{display:flex;gap:22px;border-bottom:1px solid #e0d7ca;overflow-x:auto}.chapter{display:flex;align-items:center;text-align:left;gap:10px;flex:1;min-width:120px;border:0;border-radius:0;border-bottom:2px solid transparent;padding:10px 0 12px}.chapter[aria-current=page]{border-bottom-color:#867148;color:#57451e}.chapter-number{font-family:Georgia,serif;font-size:20px;color:#b7a688}.chapter strong,.chapter small{display:block}.chapter strong{font-weight:500;font-size:14px}.chapter small{font-size:12px;color:#9b8e7c;margin-top:5px}
.navigation details{padding:10px 0;margin-bottom:10px}summary{cursor:pointer;font-size:13px;color:#797064}#work-context h3{font-size:13px;margin:16px 0 6px}#work-context ul{padding-left:20px;margin:0;line-height:1.8;font-size:13px;color:#797064}
.draft-panel{background:#fffefb;padding:20px 32px 26px;border-top:1px solid #e5dece;border-bottom:1px solid #e5dece}.draft-heading{display:flex;align-items:center;justify-content:space-between;gap:12px}.draft-heading p{font-size:12px;color:#938777;margin:5px 0 0}#chapter-label{font-size:14px;color:#766344}.actions{display:flex;align-items:center;justify-content:end;gap:8px}.actions p{font-size:12px;margin:0}.actions p:empty{display:none}.primary{background:#756348;color:#fff;border-color:#756348}
label{display:block;font-size:12px;color:#93816c;margin:14px 0 5px}input,textarea{display:block;width:100%;border:0;border-radius:0;background:transparent;color:#443c31;font-family:"Songti SC","SimSun",serif}#draft-title{border-bottom:1px solid #ddd4c7;font-size:22px;padding:8px 0 12px}textarea{font-size:18px;line-height:2;resize:vertical;min-height:600px;padding:10px 0}
.feedback{display:flex;align-items:start;justify-content:space-between;gap:14px;margin-top:14px}.feedback:has(#message:empty){margin-top:0}.feedback p{font-size:13px;line-height:1.7;margin:0;color:#8b7c66}.feedback p[data-kind=error]{color:#a03931}.feedback p[data-kind=notice]{color:#86612f}.feedback button{font-size:13px;white-space:nowrap}#error-detail{margin-top:6px}#error-code{font-size:12px}
#comparison{margin-top:24px;padding-top:20px;border-top:1px solid #e0b7af}#comparison header{display:flex;align-items:center;justify-content:space-between;gap:12px}#comparison h3{font-size:16px;margin:0}#comparison p{font-size:13px;line-height:1.7;color:#815828}#remote-body{min-height:280px;background:#faf8f5}
@media(max-width:720px){#app{margin:16px auto 24px;padding:0 14px}.work-heading h1{font-size:22px}#chapters{gap:12px}.chapter{gap:7px}.chapter strong{font-size:13px}.chapter-number{display:none}.draft-panel{padding:18px 16px}.draft-heading{flex-wrap:wrap}.actions{width:100%;flex-wrap:wrap}.actions p{margin-right:auto}textarea{font-size:17px;line-height:1.95;min-height:450px}.feedback{display:block}.feedback button{margin-top:10px}}

const $=id=>document.getElementById(id);
const parameters=new URLSearchParams(location.search);
let workId=parameters.get('work'),snapshot=null,selected=Number(parameters.get('chapter')??1),busy=false,uncertain=false;
const edits=new Map();
let pendingRemote=null;
function message(text,kind='normal',read=false,code=''){$('message').textContent=text;$('message').dataset.kind=kind;$('read-current').hidden=!read;$('error-detail').hidden=!code;$('error-code').textContent=code;$('error-detail').open=false;}
function failure(error){const text=error.code==='STALE_CHAPTER'?'这一章已保存了新稿。':error.code==='STALE_WORK'?'作品资料已有变化。':error.code?.startsWith('STALE_')?'前文章节已有变化。':error.code==='NETWORK_UNCONFIRMED'?'连接中断，尚未确认保存结果。':error.message;message(text+' 本地修改仍保留，请读取当前稿后对照。','error',true,error.code);}
async function request(path,options){let response;try{response=await fetch(path,options);}catch{const error=new Error('无法连接服务。本次请求未确认，本地修改仍保留；恢复连接后先读取当前稿。');error.code='NETWORK_UNCONFIRMED';throw error;}const value=await response.json();if(!response.ok){const error=new Error(value.error.message);error.code=value.error.code;throw error;}return value;}
function edit(){return edits.get(selected);}
function isDirty(value=edit()){return !!value&&(value.title!==value.base.title||value.body!==value.base.body);}
function sync(){const current=edit();if(!current)return;current.title=$('draft-title').value;current.body=$('draft-body').value;$('edit-state').textContent=isDirty()?'有未保存修改':'';$('save').disabled=busy||uncertain||!isDirty();}
function setBusy(value){busy=value;$('draft-title').disabled=value||!snapshot;$('draft-body').disabled=value||!snapshot;$('use-current').disabled=value;$('reload').disabled=value;$('read-current').disabled=value;$('save').disabled=value||uncertain||!isDirty();for(const button of $('chapters').querySelectorAll('button'))button.disabled=value;}
function context(){const container=$('work-context');container.replaceChildren();for(const [title,items] of [['用途',[snapshot.work.purpose]],['要求',snapshot.work.requirements],['已确认设定',snapshot.work.facts],['大纲',snapshot.work.outline.map(o=>'第 '+o.number+' 章 '+o.titleHint+'：'+o.goal)]]){const heading=document.createElement('h3');heading.textContent=title;const list=document.createElement('ul');for(const text of items){const item=document.createElement('li');item.textContent=text;list.append(item);}container.append(heading,list);}}
function navigation(){const nav=$('chapters');nav.replaceChildren();for(const chapter of snapshot.chapters){const button=document.createElement('button');button.type='button';button.className='chapter';button.dataset.number=String(chapter.number);button.setAttribute('aria-current',chapter.number===selected?'page':'false');const number=document.createElement('span');number.className='chapter-number';number.textContent=String(chapter.number).padStart(2,'0');const text=document.createElement('span');const title=document.createElement('strong');title.textContent=chapter.title;const state=document.createElement('small');state.textContent='r'+chapter.revision+' · '+(chapter.status==='draft'?'草稿':'已采用')+(chapter.basisCurrent?'':' · 依据有变动');text.append(title,state);button.append(number,text);button.addEventListener('click',()=>{sync();selected=chapter.number;pendingRemote=null;$('comparison').hidden=true;render();message('');});nav.append(button);}}
function render(){if(!snapshot)return;const chapter=snapshot.chapters.find(c=>c.number===selected);if(!chapter){message('该章尚未保存。','error');return;}if(!edits.has(selected))edits.set(selected,{base:structuredClone(chapter),workRevision:snapshot.work.revision,previous:snapshot.chapters.filter(c=>c.number<selected).map(c=>({number:c.number,revision:c.revision})),title:chapter.title,body:chapter.body});const current=edit();$('work-title').textContent=snapshot.work.title;$('chapter-label').textContent='第 '+selected+' 章 · 当前草稿';$('revision').textContent='读取 r'+current.base.revision+' · '+(current.base.status==='draft'?'草稿':'已采用')+' · '+(current.base.basisCurrent?'依据当前':'依据有变动');$('draft-title').disabled=busy;$('draft-body').disabled=busy;$('draft-title').value=current.title;$('draft-body').value=current.body;navigation();context();sync();}
async function readCurrent(){setBusy(true);try{const incoming=await request('/api/work?work='+encodeURIComponent(workId));snapshot=incoming;const chapter=incoming.chapters.find(c=>c.number===selected);if(isDirty()){pendingRemote=chapter;$('remote-heading').textContent='当前已保存稿 · r'+chapter.revision;$('remote-body').value=chapter.body;$('comparison').hidden=false;message('当前已保存稿已读回。本地修改仍在上方，请先对照。','notice');}else{edits.delete(selected);$('comparison').hidden=true;message('');}uncertain=false;render();}catch(error){failure(error);}finally{setBusy(false);}}
$('draft-title').addEventListener('input',sync);$('draft-body').addEventListener('input',sync);
$('draft-form').addEventListener('submit',async event=>{event.preventDefault();sync();if(!isDirty()||busy||uncertain)return;const current=edit();setBusy(true);message('正在保存草稿。');const input={workId,chapterNumber:selected,expectedWorkRevision:current.workRevision,expectedChapterRevision:current.base.revision,expectedPreviousRevisions:current.previous,title:current.title,body:current.body};try{const saved=await request('/api/draft',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(input)});const incoming=await request('/api/work?work='+encodeURIComponent(workId));snapshot=incoming;edits.delete(selected);pendingRemote=null;$('comparison').hidden=true;render();message('已保存 r'+saved.revision+'。');}catch(error){uncertain=error.code==='NETWORK_UNCONFIRMED'||error.code==='INTERNAL_ERROR';failure(error);}finally{setBusy(false);}});
$('reload').addEventListener('click',readCurrent);$('read-current').addEventListener('click',readCurrent);
$('use-current').addEventListener('click',()=>{if(!pendingRemote)return;edits.delete(selected);pendingRemote=null;$('comparison').hidden=true;uncertain=false;render();message('');});
window.addEventListener('beforeunload',event=>{if([...edits.values()].some(isDirty)){event.preventDefault();event.returnValue='';}});
try{if(!workId)workId=(await request('/api/config')).workId;snapshot=await request('/api/work?work='+encodeURIComponent(workId));render();message('');}catch(error){failure(error);$('draft-title').disabled=true;$('draft-body').disabled=true;}
